<?php require 'config.php';require_admin();verify_csrf();$products=read_json('products.json',[]);if($_SERVER['REQUEST_METHOD']==='POST'){ $id=$_POST['id']??'';$action=$_POST['action']??'';foreach($products as &$p)if($p['id']===$id){if($action==='delete'){$p['active']=false;}else{$p['price']=(float)$_POST['price'];$p['stock']=(int)$_POST['stock'];$p['active']=isset($_POST['active']);}}write_json('products.json',$products);flash('تم حفظ التعديل.');redirect('products.php');}$title='إدارة المنتجات';require 'header.php';?><h1>📦 إدارة المنتجات</h1><a class="btn" href="admin_product_add.php">+ إضافة منتج</a><br><br><table class="table"><tr><th>المنتج</th><th>السعر</th><th>المخزون</th><th>الحالة</th><th></th></tr><?php foreach($products as $p):?><tr><td><?=e($p['name'])?></td><td><?=money((float)$p['price'])?></td><td><?=e((string)$p['stock'])?></td><td><?=!empty($p['active'])?'ظاهر':'مخفي'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=e($p['id'])?>"><input name="price" value="<?=e((string)$p['price'])?>"><input name="stock" value="<?=e((string)$p['stock'])?>"><label><input type="checkbox" name="active" <?=!empty($p['active'])?'checked':''?>> ظاهر</label><button class="btn">حفظ</button> <button class="btn secondary" name="action" value="delete" data-confirm="إخفاء المنتج؟">إخفاء</button></form></td></tr><?php endforeach;?></table><?php require 'footer.php';?>